        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug occurs because when the target is disabled in dual mode, the entire port goes offline, which inadvertently turns off the initiator as well. The original code did not account for the scenario where the initiator mode should remain enabled even if the dual mode is not active, leading to incorrect behavior when attempting to restore the initiator mode.

        Commit message:
        scsi: qla2xxx: Restore initiator in dual mode

In dual mode in case of disabling the target, the whole port goes offline
and initiator is turned off too.

Fix restoring initiator mode after disabling target in dual mode.

Link: https://lore.kernel.org/r/20210915153239.8035-1-d.bogdanov@yadro.com
Fixes: 0645cb8350cd ("scsi: qla2xxx: Add mode control for each physical port")
Reviewed-by: Himanshu Madhani <himanshu.madhani@oracle.com>
Signed-off-by: Dmitry Bogdanov <d.bogdanov@yadro.com>
Signed-off-by: Martin K. Petersen <martin.petersen@oracle.com>  

        Patch:
         */
 int
 qla2x00_abort_isp(scsi_qla_host_t *vha)
 {
 	int rval;
 	uint8_t        status = 0;
 	struct qla_hw_data *ha = vha->hw;
 	struct scsi_qla_host *vp, *tvp;
 	struct req_que *req = ha->req_q_map[0];
 	unsigned long flags;

 	if (vha->flags.online) {
 		qla2x00_abort_isp_cleanup(vha);

 		if (vha->hw->flags.port_isolated)
 			return status;

 		if (qla2x00_isp_reg_stat(ha)) {
 			ql_log(ql_log_info, vha, 0x803f,
 			       "ISP Abort - ISP reg disconnect, exiting.\n");
 			return status;
 		}

 		if (test_and_clear_bit(ISP_ABORT_TO_ROM, &vha->dpc_flags)) {
 			ha->flags.chip_reset_done = 1;
 			vha->flags.online = 1;
 			status = 0;
 			clear_bit(ISP_ABORT_RETRY, &vha->dpc_flags);
 			return status;
 		}

 		if (IS_QLA8031(ha)) {
 			ql_dbg(ql_dbg_p3p, vha, 0xb05c,
 			    "Clearing fcoe driver presence.\n");
 			if (qla83xx_clear_drv_presence(vha) != QLA_SUCCESS)
 				ql_dbg(ql_dbg_p3p, vha, 0xb073,
 				    "Error while clearing DRV-Presence.\n");
 		}

 		if (unlikely(pci_channel_offline(ha->pdev) &&
 		    ha->flags.pci_channel_io_perm_failure)) {
 			clear_bit(ISP_ABORT_RETRY, &vha->dpc_flags);
 			status = 0;
 			return status;
 		}

 		switch (vha->qlini_mode) {
 		case QLA2XXX_INI_MODE_DISABLED:
 			if (!qla_tgt_mode_enabled(vha))
 				return 0;
 			break;
 		case QLA2XXX_INI_MODE_DUAL:
-			if (!qla_dual_mode_enabled(vha))
+			if (!qla_dual_mode_enabled(vha) &&
+			    !qla_ini_mode_enabled(vha))
 				return 0;
 			break;
 		case QLA2XXX_INI_MODE_ENABLED:
 		default:
 			break;
 		}

 		ha->isp_ops->get_flash_version(vha, req->ring);

 		if (qla2x00_isp_reg_stat(ha)) {
 			ql_log(ql_log_info, vha, 0x803f,
 			       "ISP Abort - ISP reg disconnect pre nvram config, exiting.\n");
 			return status;
 		}
 		ha->isp_ops->nvram_config(vha);

 		if (qla2x00_isp_reg_stat(ha)) {
 			ql_log(ql_log_info, vha, 0x803f,
 			       "ISP Abort - ISP reg disconnect post nvmram config, exiting.\n");
 			return status;
 		}
 		if (!qla2x00_restart_isp(vha)) {
 			clear_bit(RESET_MARKER_NEEDED, &vha->dpc_flags);

 			if (!atomic_read(&vha->loop_down_timer)) {
 				/*
 				 * Issue marker command only when we are going
 				 * to start the I/O .
 				 */
 				vha->marker_needed = 1;
 			}

 			vha->flags.online = 1;

 			ha->isp_ops->enable_intrs(ha);

 			ha->isp_abort_cnt = 0;
 			clear_bit(ISP_ABORT_RETRY, &vha->dpc_flags);

 			if (IS_QLA81XX(ha) || IS_QLA8031(ha))
 				qla2x00_get_fw_version(vha);
 			if (ha->fce) {
 				ha->flags.fce_enabled = 1;
 				memset(ha->fce, 0,
 				    fce_calc_size(ha->fce_bufs));
 				rval = qla2x00_enable_fce_trace(vha,
 				    ha->fce_dma, ha->fce_bufs, ha->fce_mb,
 				    &ha->fce_bufs);
 				if (rval) {
 					ql_log(ql_log_warn, vha, 0x8033,
 					    "Unable to reinitialize FCE "
 					    "(%d).\n", rval);
 					ha->flags.fce_enabled = 0;
 				}
 			}

 			if (ha->eft) {
 				memset(ha->eft, 0, EFT_SIZE);
 				rval = qla2x00_enable_eft_trace(vha,
 				    ha->eft_dma, EFT_NUM_BUFFERS);
 				if (rval) {
 					ql_log(ql_log_warn, vha, 0x8034,
 					    "Unable to reinitialize EFT "
 					    "(%d).\n", rval);
 				}
 			}
 		} else {	/* failed the ISP abort */
 			vha->flags.online = 1;
 			if (test_bit(ISP_ABORT_RETRY, &vha->dpc_flags)) {
 				if (ha->isp_abort_cnt == 0) {
 					ql_log(ql_log_fatal, vha, 0x8035,
 					    "ISP error recover failed - "
 					    "board disabled.\n");
 					/*
 					 * The next call disables the board
 					 * completely.
 					 */
 					qla2x00_abort_isp_cleanup(vha);
 					vha->flags.online = 0;
 					clear_bit(ISP_ABORT_RETRY,
 					    &vha->dpc_flags);
 					status = 0;
 				} else { /* schedule another ISP abort */
 					ha->isp_abort_cnt--;
 					ql_dbg(ql_dbg_taskm, vha, 0x8020,
 					    "ISP abort - retry remaining %d.\n",
 					    ha->isp_abort_cnt);
 					status = 1;
 				}
 			} else {
 				ha->isp_abort_cnt = MAX_RETRIES_OF_ISP_ABORT;
 				ql_dbg(ql_dbg_taskm, vha, 0x8021,
 				    "ISP error recovery - retrying (%d) "
 				    "more times.\n", ha->isp_abort_cnt);
 				set_bit(ISP_ABORT_RETRY, &vha->dpc_flags);
 				status = 1;
 			}
 		}

 	}

 	if (vha->hw->flags.port_isolated) {
 		qla2x00_abort_isp_cleanup(vha);
 		return status;
 	}

 	if (!status) {
 		ql_dbg(ql_dbg_taskm, vha, 0x8022, "%s succeeded.\n", __func__);
 		qla2x00_configure_hba(vha);
 		spin_lock_irqsave(&ha->vport_slock, flags);
 		list_for_each_entry_safe(vp, tvp, &ha->vp_list, list) {
 			if (vp->vp_idx) {
 				atomic_inc(&vp->vref_count);
 				spin_unlock_irqrestore(&ha->vport_slock, flags);

 				qla2x00_vp_abort_isp(vp);

 				spin_lock_irqsave(&ha->vport_slock, flags);
 				atomic_dec(&vp->vref_count);
 			}
 		}
 		spin_unlock_irqrestore(&ha->vport_slock, flags);

 		if (IS_QLA8031(ha)) {
 			ql_dbg(ql_dbg_p3p, vha, 0xb05d,
 			    "Setting back fcoe driver presence.\n");
 			if (qla83xx_set_drv_presence(vha) != QLA_SUCCESS)
 				ql_dbg(ql_dbg_p3p, vha, 0xb074,
 				    "Error while setting DRV-Presence.\n");
 		}
 	} else {
 		ql_log(ql_log_warn, vha, 0x8023, "%s **** FAILED ****.\n",
 		       __func__);
 	}

 	return(status);
 }



